import { FetchReleaseNotesMigration } from './fetch-release-notes-migration.ts';

describe('config/migrations/custom/fetch-release-notes-migration', () => {
  it('migrates', async () => {
    await expect(FetchReleaseNotesMigration).toMigrate(
      {
        fetchReleaseNotes: false,
      },
      {
        fetchChangeLogs: 'off',
      },
    );
    await expect(FetchReleaseNotesMigration).toMigrate(
      {
        fetchReleaseNotes: true,
      },
      {
        fetchChangeLogs: 'pr',
      },
    );
    await expect(FetchReleaseNotesMigration).toMigrate(
      {
        fetchReleaseNotes: 'pr',
      },
      {
        fetchChangeLogs: 'pr',
      },
    );
    await expect(FetchReleaseNotesMigration).toMigrate(
      {
        fetchReleaseNotes: 'off',
      },
      {
        fetchChangeLogs: 'off',
      },
    );
    await expect(FetchReleaseNotesMigration).toMigrate(
      {
        fetchReleaseNotes: 'branch',
      },
      {
        fetchChangeLogs: 'branch',
      },
    );
  });
});

import { isBoolean } from '@sindresorhus/is';
import type { RenovateConfig } from '../../types.ts';
import { RenamePropertyMigration } from '../base/rename-property-migration.ts';

export class FetchReleaseNotesMigration extends RenamePropertyMigration {
  constructor(originalConfig: RenovateConfig, migratedConfig: RenovateConfig) {
    super(
      'fetchReleaseNotes',
      'fetchChangeLogs',
      originalConfig,
      migratedConfig,
    );
  }

  override run(value: unknown): void {
    let newValue: unknown = value;

    if (isBoolean(value)) {
      newValue = value ? 'pr' : 'off';
    }

    super.run(newValue);
  }
}
